// Round-trip serialization tests for Nalix packets

use super::*;

#[test]
fn control_round_trip() {
    let mut pkt = Control::default();
    pkt.reason = 0x0064u16;
    pkt.r#type = 0x02u8;

    let mut buf = [0u8; Control::FIXED_SIZE];
    let written = pkt.serialize(&mut buf).expect("serialize failed");
    assert_eq!(written, Control::FIXED_SIZE);

    let parsed = Control::deserialize(&buf).expect("deserialize failed");
    assert_eq!(pkt, parsed);
}

